// Client-side Reality short_id generation (for preview and drafts only — the real key is generated by the backend)
export function generateShortIds(count = 6) {
  return Array.from({ length: count }, () => {
    const bytes = new Uint8Array(4)
    crypto.getRandomValues(bytes)
    return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  })
}

// Random password: ambiguous characters (0/O, 1/l/I) removed, default length 16, entropy from crypto.getRandomValues
const PASSWORD_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789'
export function generatePassword(length = 16) {
  const bytes = new Uint32Array(length)
  crypto.getRandomValues(bytes)
  return Array.from(bytes, (n) => PASSWORD_ALPHABET[n % PASSWORD_ALPHABET.length]).join('')
}
